export function getRandomElement(array) {
  return array[Math.floor(Math.random() * array.length)];
}

export function getVariantForIntent(intent, type, seedKey) {
  const category = INTENT_VARIANTS[intent] || INTENT_VARIANTS['travel-guide'];
  const pool = category[type] || category.checklist;
  if (!Array.isArray(pool) || pool.length === 0) return null;
  if (seedKey === undefined || seedKey === null || seedKey === "") {
    return pool[0];
  }
  const hash = crypto
    .createHash("sha256")
    .update(`${intent}:${type}:${seedKey}`)
    .digest();
  return pool[hash.readUInt32BE(0) % pool.length];
}

export function getLocationFact(locationKey, seedKey) {
  const pool = LOCATION_FACT_BLOCKS[locationKey];
  if (!Array.isArray(pool) || pool.length === 0) return null;
  if (seedKey === undefined || seedKey === null || seedKey === "") {
    return pool[0];
  }
  const hash = crypto
    .createHash("sha256")
    .update(`location:${locationKey}:${seedKey}`)
    .digest();
  return pool[hash.readUInt32BE(0) % pool.length];
}

export function getFaqVariant(seedKey) {
  if (!Array.isArray(FAQ_VARIANTS) || FAQ_VARIANTS.length === 0) return null;
  if (seedKey === undefined || seedKey === null || seedKey === "") {
    return FAQ_VARIANTS[0];
  }
  const hash = crypto
    .createHash("sha256")
    .update(`faq:${seedKey}`)
    .digest();
  return FAQ_VARIANTS[hash.readUInt32BE(0) % FAQ_VARIANTS.length];
}

